module.exports = "';\nconst _STATS_B64 = '';\nconst _TERRENOS_B64 = '';\nconst _KPIS_B64 = 'eyJ0b3RhbCI6Mjc3NTksInByaW9yaWRhZGVfYSI6MzQxMCwic2NvcmVfbWVkaW8iOjQ2LjExNjc5MDk1MDY4MjY2LCJwYXNzb2lyZXMiOjQ2MTIsImNvbV90ZXJyZW5vX2dyYW5kZSI6MTE3ODcsInZhbG9yX3RvdGFsX2VzdGltYWRvIjo1MzAxNDEyNjAwLjB9';\nfunction _b64json(s){ return JSON.parse(decodeURIComponent(escape(atob(s)))); }\nconst LEADS = _b64json(_LEADS_B64);\nconst STATS = _b64json(_STATS_B64);\nconst TERRENOS = _b64json(_TERRENOS_B64);\nconst KPIS = _b64json(_KPIS_B64);\n\nconst COLS = ['adresse','commune','secteur','prioridade','score','tipo','superficie','pieces',\n              'dpe','passoire','ano','terreno','prixm2','valor','maisvalia','duree',\n              'argDpe','argTerreno','argPrudent','nbComp','echeanceDpe','gmaps','motivos','comparaveis','superficieDpe','fichaIdx','sourceSurface'];\nconst IDX = Object.fromEntries(COLS.map((c,i)=>[c,i]));\n\nconst TCOLS = ['parcela','commune','area','zonaPlu','zonaLibelle','poiAlerta','linkMapa'];\nconst TIDX = Object.fromEntries(TCOLS.map((c,i)=>[c,i]));\n\nconst fmtEUR = new Intl.NumberFormat('fr-FR',{style:'currency',currency:'EUR',maximumFractionDigits:0});\nconst fmtNum = new Intl.NumberFormat('fr-FR');\nconst fmtPct = (v)=> (v>0?'+':'') + v.toFixed(1).replace('.',',') + ' %';\nconst fmtCompactEUR = (v)=> v>=1e6 ? (v/1e6).toFixed(1).replace('.',',') + ' M €' : fmtEUR.format(v);\n\nconst state = { search:'', priority:'ALL', commune:'', passoireOnly:false, terrenoOnly:false,\n                periodo:'', tipoView:'TODOS', sortKey: IDX.score, sortDir:-1, tSortKey: TIDX.area, tSortDir:-1,\n                page:1, pageSize:40 };\n\nfunction dpeClass(d){\n  if(!d) return 'mid';\n  if(['A','B'].includes(d)) return 'good';\n  if(['E','F','G'].includes(d)) return 'bad';\n  return 'mid';\n}\n\nfunction tipoMatches(r){\n  if(state.tipoView === 'CASAS') return r[IDX.tipo] === 'Maison';\n  if(state.tipoView === 'APARTAMENTOS') return r[IDX.tipo] === 'Appartement';\n  return true;\n}\n\nfunction buildKpis(){\n  const el = document.getElementById('kpiRow');\n  let tiles;\n  if(state.tipoView === 'TERRENOS'){\n    const total = TERRENOS.length;\n    const totalArea = TERRENOS.reduce((s,r)=>s+(r[TIDX.area]||0),0);\n    const communes = new Set(TERRENOS.map(r=>r[TIDX.commune])).size;\n    const avgArea = total ? totalArea/total : 0;\n    tiles = [\n      {label:'Terrains libres identifiés', value: fmtNum.format(total), sub:'≥ 500 m² · zone U'},\n      {label:'Surface cumulée', value: fmtNum.format(Math.round(totalArea))+' m²', sub:'toutes parcelles'},\n      {label:'Surface moyenne', value: fmtNum.format(Math.round(avgArea))+' m²', sub:'par parcelle'},\n      {label:'Communes couvertes', value: fmtNum.format(communes), sub:'sur les 26 communes d\\'origine'},\n    ];\n  } else {\n    tiles = [\n      {label:'Adresses prioritaires', value: fmtNum.format(KPIS.total), sub:'score ≥ 40'},\n      {label:'Priorité maximale', value: fmtNum.format(KPIS.prioridade_a), sub:'score ≥ 70', gold:true},\n      {label:'Score moyen', value: KPIS.score_medio.toFixed(1).replace('.',','), sub:'sur 100'},\n      {label:'Passoires thermiques', value: fmtNum.format(KPIS.passoires), sub:'DPE E · F · G'},\n      {label:'Terrain ≥ 1000 m²', value: fmtNum.format(KPIS.com_terreno_grande), sub:'potentiel de division'},\n      {label:'Valeur du portefeuille', value: fmtCompactEUR(KPIS.valor_total_estimado), sub:'estimation agrégée'},\n    ];\n  }\n  el.innerHTML = tiles.map(t=>`\n    <div class=\"kpi\">\n      <div class=\"kpi-label\">${t.label}</div>\n      <div class=\"kpi-value${t.gold?' gold':''}\">${t.value}</div>\n      <div class=\"kpi-sub\">${t.sub}</div>\n    </div>`).join('');\n}\n\nfunction buildCommuneSelect(){\n  const sel = document.getElementById('communeSelect');\n  const names = [...new Set(STATS.map(s=>s[0]))].sort((a,b)=>a.localeCompare(b,'fr'));\n  names.forEach(n=>{\n    const o = document.createElement('option');\n    o.value = n; o.textContent = n;\n    sel.appendChild(o);\n  });\n}\n\nfunction buildCommunePanel(){\n  const list = document.getElementById('communeList');\n  const rows = [...STATS].sort((a,b)=> (b[4]||0) - (a[4]||0));\n  const max = Math.max(...rows.map(r=>r[4]||0));\n  list.innerHTML = rows.map(r=>{\n    const [commune,, nbVentes, prixBrut, prixActualise, evo, tauxAnnuel] = r;\n    const pct = max ? Math.round((prixActualise||0)/max*100) : 0;\n    const upFlag = (tauxAnnuel||0) >= 0;\n    return `<div class=\"commune-row\" data-commune=\"${commune}\">\n      <span class=\"commune-name\">${commune}</span>\n      <span class=\"commune-val\">${fmtNum.format(prixActualise||0)} €</span>\n      <div class=\"commune-bar-track\"><div class=\"commune-bar-fill\" style=\"width:${pct}%\"></div></div>\n      <div class=\"commune-meta\">\n        <span>${fmtNum.format(nbVentes||0)} ventes · brut ${fmtNum.format(prixBrut||0)} €</span>\n        <span class=\"evo ${upFlag?'up':'down'}\">${upFlag?'▲':'▼'} ${Math.abs(tauxAnnuel||0).toFixed(1)}%/an</span>\n      </div>\n    </div>`;\n  }).join('');\n  list.querySelectorAll('.commune-row').forEach(row=>{\n    row.addEventListener('click', ()=>{\n      const c = row.dataset.commune;\n      state.commune = (state.commune === c) ? '' : c;\n      document.getElementById('communeSelect').value = state.commune;\n      state.page = 1;\n      render();\n    });\n  });\n}\n\nfunction periodoOf(ano){\n  if(ano==null) return 'INCONNU';\n  const a = Math.round(ano);\n  if(a < 1948) return 'AVANT_1948';\n  if(a < 1975) return '1948_1974';\n  if(a < 2000) return '1975_1999';\n  if(a <= 2016) return '2000_2016';\n  return '2016_2026';\n}\n\nfunction filtered(){\n  let rows = LEADS.filter(tipoMatches);\n  if(state.priority !== 'ALL') rows = rows.filter(r=>r[IDX.prioridade]===state.priority);\n  if(state.commune) rows = rows.filter(r=>r[IDX.commune]===state.commune);\n  if(state.passoireOnly) rows = rows.filter(r=>r[IDX.passoire]===true);\n  if(state.terrenoOnly) rows = rows.filter(r=>(r[IDX.terreno]||0) >= 1000);\n  if(state.periodo) rows = rows.filter(r=>periodoOf(r[IDX.ano])===state.periodo);\n  if(state.search){\n    const q = state.search.toLowerCase();\n    rows = rows.filter(r=> (r[IDX.adresse]||'').toLowerCase().includes(q) || (r[IDX.commune]||'').toLowerCase().includes(q));\n  }\n  const key = state.sortKey, dir = state.sortDir;\n  rows = [...rows].sort((a,b)=>{\n    const av = a[key], bv = b[key];\n    if(av==null && bv==null) return 0;\n    if(av==null) return 1;\n    if(bv==null) return -1;\n    if(typeof av === 'string') return dir * av.localeCompare(bv,'fr');\n    return dir * (av - bv);\n  });\n  return rows;\n}\n\nfunction filteredTerrenos(){\n  let rows = TERRENOS;\n  if(state.commune) rows = rows.filter(r=>r[TIDX.commune]===state.commune);\n  if(state.search){\n    const q = state.search.toLowerCase();\n    rows = rows.filter(r=> (r[TIDX.parcela]||'').toLowerCase().includes(q) || (r[TIDX.commune]||'').toLowerCase().includes(q));\n  }\n  const key = state.tSortKey, dir = state.tSortDir;\n  rows = [...rows].sort((a,b)=>{\n    const av = a[key], bv = b[key];\n    if(av==null && bv==null) return 0;\n    if(av==null) return 1;\n    if(bv==null) return -1;\n    if(typeof av === 'string') return dir * av.localeCompare(bv,'fr');\n    return dir * (av - bv);\n  });\n  return rows;\n}\n\nfunction rowDetail(r, idx){\n  const blocks = [];\n  if(r[IDX.argDpe]) blocks.push({h:'Argument — passoire thermique', p:r[IDX.argDpe]});\n  if(r[IDX.argTerreno]) blocks.push({h:'Argument — terrain', p:r[IDX.argTerreno]});\n  if(r[IDX.argPrudent]) blocks.push({h:'Argument — tendance de marché', p:r[IDX.argPrudent]});\n  blocks.push({h:'Motifs du score', p:r[IDX.motivos] || '—'});\n  if(r[IDX.comparaveis]) blocks.push({h:'Ventes comparables (prix réel de l\\'année)', p:r[IDX.comparaveis]});\n  const compTxt = r[IDX.nbComp] ? `${r[IDX.nbComp]} vente(s) comparable(s) dans la rue/commune` : 'Aucun comparable direct dans cette rue';\n  const srcLbl = {DPE:'DPE — surface habitable mesurée', DVF:'DVF — fichiers fonciers, souvent sous-estimée'};\n  const surfaceInfo = r[IDX.superficie]!=null ? `${Math.round(r[IDX.superficie])} m² (${srcLbl[r[IDX.sourceSurface]] || 'DVF'})` : (r[IDX.superficieDpe]!=null ? `${Math.round(r[IDX.superficieDpe])} m² (DPE)` : 'surface inconnue');\n  return `<div class=\"detail-grid\">\n    ${blocks.map(b=>`<div class=\"detail-block\"><h4>${b.h}</h4><p class=\"argument-quote\">${b.p}</p></div>`).join('')}\n    <div class=\"detail-block\"><h4>Base d'estimation</h4><p>${compTxt}. Surface : ${surfaceInfo}. Année de construction : ${r[IDX.ano]||'inconnue'}. Ancienneté de détention : ${r[IDX.duree]!=null? r[IDX.duree]+' ans' : 'jamais vendu sur la fenêtre DVF'}. Prix au m² actualisé à 2025.</p></div>\n  </div>\n  <div class=\"cta-row\">\n    ${r[IDX.gmaps] ? `<a class=\"cta\" href=\"${r[IDX.gmaps]}\" target=\"_blank\" rel=\"noopener\">Voir sur la carte ↗</a>` : ''}\n    ${r[IDX.fichaIdx]!=null ? `<a class=\"cta\" href=\"/api/ficha?n=${r[IDX.fichaIdx]}\" target=\"_blank\" rel=\"noopener\">Télécharger la fiche PDF ↓</a>` : ''}\n  </div>`;\n}\n\nfunction renderLeads(){\n  const rows = filtered();\n  const total = rows.length;\n  const pages = Math.max(1, Math.ceil(total/state.pageSize));\n  state.page = Math.min(state.page, pages);\n  const start = (state.page-1)*state.pageSize;\n  const pageRows = rows.slice(start, start+state.pageSize);\n\n  const tbody = document.getElementById('tbody');\n  if(pageRows.length === 0){\n    tbody.innerHTML = `<tr><td colspan=\"8\" class=\"empty-state\">Aucune adresse ne correspond à ces filtres.</td></tr>`;\n  } else {\n    tbody.innerHTML = pageRows.map((r,i)=>{\n      const gi = start+i;\n      const dc = dpeClass(r[IDX.dpe]);\n      const priorityCls = r[IDX.prioridade]==='A' ? 'pA' : 'pB';\n      const priorityLbl = ({A:'A · maximale', B:'B · élevée', C:'C · moyenne', D:'D · faible'})[r[IDX.prioridade]] || (r[IDX.prioridade]||'—');\n      const mv = r[IDX.maisvalia];\n      const superficie = r[IDX.superficie]!=null ? r[IDX.superficie] : r[IDX.superficieDpe];\n      return `<tr class=\"row\" data-idx=\"${gi}\">\n        <td><span class=\"chev\">▸</span><span class=\"pill ${priorityCls}\">${priorityLbl}</span><br>\n            <span class=\"addr\">${r[IDX.adresse]||'—'}</span><span class=\"addr-sub\">${r[IDX.commune]||''} · ${r[IDX.secteur]||''}</span></td>\n        <td class=\"num\">${r[IDX.score]!=null?r[IDX.score]:'—'}</td>\n        <td>${r[IDX.tipo]||'—'}</td>\n        <td class=\"num\">${superficie!=null?Math.round(superficie)+' m²':'—'}</td>\n        <td><div class=\"dpe-wrap\"><span class=\"badge-dpe ${dc}\">${r[IDX.dpe]||'?'}</span>${r[IDX.echeanceDpe]?`<span class=\"dpe-echeance\">interdit ${r[IDX.echeanceDpe]}</span>`:''}</div></td>\n        <td class=\"num\">${r[IDX.terreno]!=null?Math.round(r[IDX.terreno])+' m²':'—'}</td>\n        <td class=\"num\">${r[IDX.valor]!=null?fmtEUR.format(r[IDX.valor]):'—'}</td>\n        <td class=\"num\">${mv!=null?fmtPct(mv):'—'}</td>\n      </tr>\n      <tr class=\"detail\" data-detail-for=\"${gi}\"><td colspan=\"8\">${rowDetail(r,gi)}</td></tr>`;\n    }).join('');\n\n    tbody.querySelectorAll('tr.row').forEach(tr=>{\n      tr.addEventListener('click', (e)=>{\n        if(e.target.closest('a')) return;\n        const idx = tr.dataset.idx;\n        const det = tbody.querySelector(`tr.detail[data-detail-for=\"${idx}\"]`);\n        tr.classList.toggle('open');\n        det.classList.toggle('open');\n      });\n    });\n  }\n\n  document.getElementById('countBadge').innerHTML = `<b>${fmtNum.format(total)}</b> sur ${fmtNum.format(LEADS.length)} adresses`;\n  document.getElementById('pageLabel').textContent = `Page ${state.page} sur ${pages}`;\n  document.getElementById('prevPage').disabled = state.page<=1;\n  document.getElementById('nextPage').disabled = state.page>=pages;\n\n  document.querySelectorAll('.commune-row').forEach(row=>{\n    row.classList.toggle('active', row.dataset.commune === state.commune);\n  });\n}\n\nfunction renderTerrenos(){\n  const rows = filteredTerrenos();\n  const total = rows.length;\n  const pages = Math.max(1, Math.ceil(total/state.pageSize));\n  state.page = Math.min(state.page, pages);\n  const start = (state.page-1)*state.pageSize;\n  const pageRows = rows.slice(start, start+state.pageSize);\n\n  const tbody = document.getElementById('tbodyTerrenos');\n  if(pageRows.length === 0){\n    tbody.innerHTML = `<tr><td colspan=\"7\" class=\"empty-state\">Aucun terrain ne correspond à ces filtres.</td></tr>`;\n  } else {\n    tbody.innerHTML = pageRows.map(r=>{\n      return `<tr>\n        <td>${r[TIDX.parcela]||'—'}</td>\n        <td>${r[TIDX.commune]||'—'}</td>\n        <td class=\"num\">${r[TIDX.area]!=null?fmtNum.format(Math.round(r[TIDX.area]))+' m²':'—'}</td>\n        <td>${r[TIDX.zonaPlu]||'—'}</td>\n        <td>${r[TIDX.zonaLibelle]||'—'}</td>\n        <td>${r[TIDX.poiAlerta] ? `<span class=\"poi-alerta\">⚠ ${r[TIDX.poiAlerta]}</span>` : '—'}</td>\n        <td>${r[TIDX.linkMapa] ? `<a class=\"cta\" href=\"${r[TIDX.linkMapa]}\" target=\"_blank\" rel=\"noopener\">Voir sur la carte ↗</a>` : '—'}</td>\n      </tr>`;\n    }).join('');\n  }\n\n  document.getElementById('countBadge').innerHTML = `<b>${fmtNum.format(total)}</b> sur ${fmtNum.format(TERRENOS.length)} terrains`;\n  document.getElementById('pageLabel').textContent = `Page ${state.page} sur ${pages}`;\n  document.getElementById('prevPage').disabled = state.page<=1;\n  document.getElementById('nextPage').disabled = state.page>=pages;\n\n  document.querySelectorAll('.commune-row').forEach(row=>{\n    row.classList.toggle('active', row.dataset.commune === state.commune);\n  });\n}\n\nfunction render(){\n  if(state.tipoView === 'TERRENOS') renderTerrenos();\n  else renderLeads();\n}\n\nfunction updateModeUI(){\n  const isTerrenos = state.tipoView === 'TERRENOS';\n  document.getElementById('leadsTable').hidden = isTerrenos;\n  document.getElementById('terrenosTable').hidden = !isTerrenos;\n  document.getElementById('prioritySeg').style.display = isTerrenos ? 'none' : '';\n  document.getElementById('passoireLabel').style.display = isTerrenos ? 'none' : '';\n  document.getElementById('terrenoLabel').style.display = isTerrenos ? 'none' : '';\n  document.getElementById('periodoSelect').style.display = isTerrenos ? 'none' : '';\n}\n\n// -------------------------------------------------------- ROTEIRO DE PROSPECÇÃO ---\n// Regroupe les adresses de plus fort potentiel d'une commune et propose un ordre de\n// visite (plus proche voisin, à vol d'oiseau) — un point de départ pour organiser une\n// tournée, pas un calcul d'itinéraire routier réel. N'utilise que des données déjà\n// présentes dans le dashboard (lat/lon extraits du lien Google Maps déjà embarqué),\n// aucune nouvelle donnée ni service externe.\nfunction extractLatLon(gmapsUrl){\n  if(!gmapsUrl) return null;\n  const m = gmapsUrl.match(/query=(-?\\d+\\.?\\d*),(-?\\d+\\.?\\d*)/);\n  if(!m) return null;\n  return { lat: parseFloat(m[1]), lon: parseFloat(m[2]) };\n}\n\nfunction haversineKm(a, b){\n  const R = 6371;\n  const dLat = (b.lat-a.lat) * Math.PI/180;\n  const dLon = (b.lon-a.lon) * Math.PI/180;\n  const la1 = a.lat * Math.PI/180, la2 = b.lat * Math.PI/180;\n  const h = Math.sin(dLat/2)**2 + Math.cos(la1)*Math.cos(la2)*Math.sin(dLon/2)**2;\n  return 2 * R * Math.asin(Math.sqrt(h));\n}\n\n// Heurística do vizinho mais próximo: parte da morada de maior score e, a cada passo,\n// escolhe a mais próxima ainda não visitada. Não é o TSP ótimo, mas é rápido e dá uma\n// rota razoável para um punhado de paragens (5-20).\nfunction buildRoute(points){\n  if(points.length === 0) return [];\n  const remaining = [...points];\n  const route = [remaining.shift()];\n  while(remaining.length){\n    const last = route[route.length-1];\n    let bestIdx = 0, bestDist = Infinity;\n    remaining.forEach((p,i)=>{\n      const d = haversineKm(last, p);\n      if(d < bestDist){ bestDist = d; bestIdx = i; }\n    });\n    const [next] = remaining.splice(bestIdx,1);\n    next._distFromPrev = bestDist;\n    route.push(next);\n  }\n  return route;\n}\n\nfunction buildRouteCommuneSelect(){\n  const sel = document.getElementById('routeCommune');\n  const names = [...new Set(LEADS.map(r=>r[IDX.commune]).filter(Boolean))].sort((a,b)=>a.localeCompare(b,'fr'));\n  names.forEach(n=>{\n    const o = document.createElement('option');\n    o.value = n; o.textContent = n;\n    sel.appendChild(o);\n  });\n}\n\nfunction generateRoute(){\n  const commune = document.getElementById('routeCommune').value;\n  const prio = document.getElementById('routePriority').value;\n  const count = parseInt(document.getElementById('routeCount').value, 10);\n  const resultEl = document.getElementById('routeResult');\n\n  if(!commune){\n    resultEl.innerHTML = '<p class=\"route-empty\">Choisis une commune pour générer un itinéraire.</p>';\n    return;\n  }\n\n  let rows = LEADS.filter(r => r[IDX.commune] === commune);\n  if(prio === 'A') rows = rows.filter(r => r[IDX.prioridade] === 'A');\n  rows = [...rows].sort((a,b)=> (b[IDX.score]||0) - (a[IDX.score]||0)).slice(0, count);\n\n  const points = rows.map(r=>{\n    const ll = extractLatLon(r[IDX.gmaps]);\n    return ll ? { ...ll, row: r } : null;\n  }).filter(Boolean);\n\n  if(points.length === 0){\n    resultEl.innerHTML = '<p class=\"route-empty\">Aucune coordonnée disponible pour cette sélection.</p>';\n    return;\n  }\n\n  const route = buildRoute(points);\n  const listHtml = route.map((p,i)=>{\n    const r = p.row;\n    const distTxt = i===0 ? 'point de départ' : `+${p._distFromPrev.toFixed(1)} km`;\n    return `<li>\n      <span class=\"route-addr\">${r[IDX.adresse]} <span class=\"route-score\">— score ${r[IDX.score]}</span></span>\n      <span class=\"route-dist\">${distTxt}</span>\n    </li>`;\n  }).join('');\n\n  const totalKm = route.reduce((s,p)=> s + (p._distFromPrev||0), 0);\n  const waypoints = route.map(p=>`${p.lat},${p.lon}`);\n  const origin = waypoints[0];\n  const destination = waypoints[waypoints.length-1];\n  const middle = waypoints.slice(1,-1).join('|');\n  let mapsUrl = `https://www.google.com/maps/dir/?api=1&origin=${origin}&destination=${destination}`;\n  if(middle) mapsUrl += `&waypoints=${encodeURIComponent(middle)}`;\n\n  resultEl.innerHTML = `\n    <p style=\"margin:0 0 .6rem 0; font-size:.82rem; color:var(--ink-soft);\">\n      ${route.length} arrêts · ${totalKm.toFixed(1)} km à vol d'oiseau entre les points (distance routière réelle probablement plus longue)\n    </p>\n    <ul class=\"route-list\">${listHtml}</ul>\n    <a class=\"route-open\" href=\"${mapsUrl}\" target=\"_blank\" rel=\"noopener\">Ouvrir l'itinéraire dans Google Maps ↗</a>\n  `;\n}\n\nfunction init(){\n  buildKpis();\n  buildCommuneSelect();\n  buildCommunePanel();\n  buildRouteCommuneSelect();\n  updateModeUI();\n\n  document.getElementById('searchInput').addEventListener('input', (e)=>{\n    state.search = e.target.value.trim();\n    state.page = 1;\n    render();\n  });\n  document.querySelectorAll('#tipoSeg button').forEach(btn=>{\n    btn.addEventListener('click', ()=>{\n      document.querySelectorAll('#tipoSeg button').forEach(b=>b.classList.remove('active'));\n      btn.classList.add('active');\n      state.tipoView = btn.dataset.val;\n      state.page = 1;\n      updateModeUI();\n      buildKpis();\n      render();\n    });\n  });\n  document.querySelectorAll('#prioritySeg button').forEach(btn=>{\n    btn.addEventListener('click', ()=>{\n      document.querySelectorAll('#prioritySeg button').forEach(b=>b.classList.remove('active'));\n      btn.classList.add('active');\n      state.priority = btn.dataset.val;\n      state.page = 1;\n      render();\n    });\n  });\n  document.getElementById('communeSelect').addEventListener('change', (e)=>{\n    state.commune = e.target.value;\n    state.page = 1;\n    render();\n  });\n  document.getElementById('periodoSelect').addEventListener('change', (e)=>{\n    state.periodo = e.target.value;\n    state.page = 1;\n    render();\n  });\n  document.getElementById('passoireToggle').addEventListener('change', (e)=>{\n    state.passoireOnly = e.target.checked;\n    state.page = 1;\n    render();\n  });\n  document.getElementById('terrenoToggle').addEventListener('change', (e)=>{\n    state.terrenoOnly = e.target.checked;\n    state.page = 1;\n    render();\n  });\n  document.querySelectorAll('#leadsTable thead th[data-key]').forEach(th=>{\n    th.addEventListener('click', ()=>{\n      const key = parseInt(th.dataset.key,10);\n      if(state.sortKey === key) state.sortDir *= -1;\n      else { state.sortKey = key; state.sortDir = -1; }\n      document.querySelectorAll('#leadsTable thead th').forEach(h=>h.classList.remove('sorted'));\n      th.classList.add('sorted');\n      const arrow = th.querySelector('.arrow');\n      if(arrow) arrow.textContent = state.sortDir===-1 ? '▼' : '▲';\n      render();\n    });\n  });\n  document.querySelectorAll('#terrenosTable thead th[data-tkey]').forEach(th=>{\n    th.addEventListener('click', ()=>{\n      const key = parseInt(th.dataset.tkey,10);\n      if(state.tSortKey === key) state.tSortDir *= -1;\n      else { state.tSortKey = key; state.tSortDir = -1; }\n      document.querySelectorAll('#terrenosTable thead th').forEach(h=>h.classList.remove('sorted'));\n      th.classList.add('sorted');\n      const arrow = th.querySelector('.arrow');\n      if(arrow) arrow.textContent = state.tSortDir===-1 ? '▼' : '▲';\n      render();\n    });\n  });\n  document.getElementById('prevPage').addEventListener('click', ()=>{ state.page--; render(); });\n  document.getElementById('nextPage').addEventListener('click', ()=>{ state.page++; render(); });\n\n  document.getElementById('routeToggleBtn').addEventListener('click', ()=>{\n    const panel = document.getElementById('routePanel');\n    panel.hidden = !panel.hidden;\n  });\n  document.getElementById('routeGenerateBtn').addEventListener('click', generateRoute);\n\n  render();\n}\n\ninit();\n\n</script>\n\n\n\n</body></html>";
